import { UsuarioService } from './usuario.service';

/**
 * Servicio para gestionar la cesta de la compra.
 * Permite agregar, eliminar, listar productos y calcular el total.
 * La cesta se guarda en localStorage, diferenciando entre usuario logueado y visitante.
 */
@Injectable({
  providedIn: 'root'
})
export class CestaService {

  /**
   * Constructor del servicio.
   * @param usuarioService Servicio de usuario para identificar al usuario actual.
   */
  constructor(private usuarioService: UsuarioService) {}

  /**
   * Obtiene la clave de la cesta en localStorage.
   * - Si hay usuario logueado: `cart_emailDelUsuario`
   * - Si no hay usuario: `cart_guest`
   * @returns Clave de la cesta en localStorage.
   */
  private getCartKey(): string {
    const user = this.usuarioService.getUsuarioActual();
    return user ? `cart_${user.email}` : 'cart_guest';
  }

  /**
   * Devuelve la cesta completa desde localStorage.
   * @returns Array de productos en la cesta.
   */
  getCesta(): any[] {
    return JSON.parse(localStorage.getItem(this.getCartKey()) || '[]');
  }

  /**
   * Alias de `getCesta`: devuelve los productos de la cesta.
   * @returns Array de productos.
   */
  getProductos(): any[] {
    return this.getCesta();
  }

  /**
   * Agrega un producto a la cesta sin controlar duplicados.
   * @param producto Producto a añadir.
   */
  agregar(producto: any): void {
    const cesta = this.getCesta();
    cesta.push(producto);
    localStorage.setItem(this.getCartKey(), JSON.stringify(cesta));
  }

  /**
   * Elimina un producto de la cesta por su ID.
   * @param id Identificador del producto a eliminar.
   */
  eliminarProducto(id: number): void {
    let cesta = this.getCesta();
    cesta = cesta.filter((p: any) => p.id !== id);
    localStorage.setItem(this.getCartKey(), JSON.stringify(cesta));
  }

  /**
   * Calcula el total de la cesta sumando los precios de todos los productos.
   * @returns Total numérico de la cesta.
   */
  getTotal(): number {
    const cesta = this.getCesta();
    return cesta.reduce((sum: number, p: any) => sum + Number(p.precio), 0);
  }

  /**
   * Limpia la cesta eliminando la clave del localStorage.
   */
  limpiar(): void {
    localStorage.removeItem(this.getCartKey());
  }

  /**
   * Vacía la cesta (alias de `limpiar`).
   */
  vaciar(): void {
    this.limpiar();
  }

  /**
   * Agrega un producto a la cesta controlando duplicados:
   * - Si ya existe, incrementa la cantidad.
   * - Si no existe, lo añade con cantidad = 1.
   * @param producto Producto a añadir o incrementar.
   */
  addProducto(producto: any): void {
    const cesta = this.getCesta();

    const existe = cesta.find((p: any) => p.id === producto.id);

    if (existe) {
      existe.cantidad = (existe.cantidad || 1) + 1;
    } else {
      cesta.push({ ...producto, cantidad: 1 });
    }

    localStorage.setItem(this.getCartKey(), JSON.stringify(cesta));
  }
}

import { Injectable } from '@angular/core';

declare const Handlebars: any;

@Injectable({
  providedIn: 'root'
})
export class HbsRenderService {
  private handlebarsInstance: any;

  constructor() {
    this.initializeHandlebars();
  }

  private initializeHandlebars() {
    // Create a new Handlebars instance for the playground
    this.handlebarsInstance = Handlebars.create();

    // Register common helpers used in Compodoc templates
    this.registerHelpers();
  }

  private registerHelpers() {
    // Register the 'compare' helper
    this.handlebarsInstance.registerHelper('compare', (left: any, operator: string, right: any, options: any) => {
      let result;
      switch (operator) {
        case '===':
          result = left === right;
          break;
        case '!==':
          result = left !== right;
          break;
        case '<':
          result = left < right;
          break;
        case '>':
          result = left > right;
          break;
        case '<=':
          result = left <= right;
          break;
        case '>=':
          result = left >= right;
          break;
        default:
          result = false;
      }
      return result ? options.fn(this) : options.inverse(this);
    });

    // Register the 'unless' helper
    this.handlebarsInstance.registerHelper('unless', (conditional: any, options: any) => {
      return !conditional ? options.fn(this) : options.inverse(this);
    });

    // Register the 'each' helper with index
    this.handlebarsInstance.registerHelper('each', (context: any, options: any) => {
      let ret = '';
      for (let i = 0; i < context.length; i++) {
        ret += options.fn(context[i], { data: { index: i } });
      }
      return ret;
    });

    // Register the 'if' helper
    this.handlebarsInstance.registerHelper('if', (conditional: any, options: any) => {
      return conditional ? options.fn(this) : options.inverse(this);
    });

    // Register the 'relativeURL' helper
    this.handlebarsInstance.registerHelper('relativeURL', (depth: number, page?: string) => {
      let url = '';
      for (let i = 0; i < depth; i++) {
        url += '../';
      }
      return url + (page || '');
    });

    // Register the 't' helper for translations
    this.handlebarsInstance.registerHelper('t', (key: string) => {
      // Simple translation mapping for preview
      const translations: { [key: string]: string } = {
        'info': 'Information',
        'source': 'Source',
        'example': 'Example',
        'template': 'Template',
        'styles': 'Styles',
        'component': 'Component',
        'module': 'Module',
        'overview': 'Overview',
        'components': 'Components',
        'modules': 'Modules',
        'file': 'File',
        'description': 'Description',
        'selector': 'Selector',
        'properties': 'Properties',
        'methods': 'Methods',
        'inputs': 'Inputs',
        'outputs': 'Outputs'
      };
      return translations[key] || key;
    });

    // Register the 'orLength' helper
    this.handlebarsInstance.registerHelper('orLength', (...args: any[]) => {
      const options = args[args.length - 1];
      const values = args.slice(0, -1);

      for (const value of values) {
        if (value && value.length && value.length > 0) {
          return options.fn(this);
        }
      }
      return options.inverse(this);
    });

    // Register the 'isTabEnabled' helper
    this.handlebarsInstance.registerHelper('isTabEnabled', (navTabs: any[], tabId: string, options: any) => {
      const tab = navTabs && navTabs.find((t: any) => t.id === tabId);
      return tab ? options.fn(this) : options.inverse(this);
    });

    // Register the 'isInitialTab' helper
    this.handlebarsInstance.registerHelper('isInitialTab', (navTabs: any[], tabId: string, options: any) => {
      const isInitial = navTabs && navTabs.length > 0 && navTabs[0].id === tabId;
      return isInitial ? options.fn(this) : options.inverse(this);
    });
  }

  renderTemplate(templateContent: string, data: any): string {
    try {
      // Create a complete HTML document for preview
      const template = this.handlebarsInstance.compile(templateContent);
      const rendered = template({ data });

      // Wrap in a basic HTML structure for preview
      return `
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="utf-8">
          <title>Template Preview</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 20px; }
            .preview-wrapper { border: 1px solid #ddd; padding: 20px; }
            .preview-notice { background: #f0f8ff; padding: 10px; margin-bottom: 20px; border-left: 4px solid #007bff; }
          </style>
        </head>
        <body>
          <div class="preview-notice">
            <strong>Template Preview:</strong> This is a live preview of your template with mock data.
          </div>
          <div class="preview-wrapper">
            ${rendered}
          </div>
        </body>
        </html>
      `;
    } catch (error) {
      return `
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="utf-8">
          <title>Template Preview - Error</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 20px; }
            .error { color: red; background: #fff5f5; padding: 20px; border: 1px solid #red; }
          </style>
        </head>
        <body>
          <div class="error">
            <h3>Template Error</h3>
            <p><strong>Error:</strong> ${error.message}</p>
            <p>Please check your template syntax and try again.</p>
          </div>
        </body>
        </html>
      `;
    }
  }

  getMockData(): any {
    return {
      documentationMainName: 'Sample Documentation',
      depth: 0,
      context: 'component',
      components: [
        {
          name: 'SampleComponent',
          selector: 'app-sample',
          file: 'src/app/sample/sample.component.ts',
          description: 'A sample component for demonstration',
          properties: [
            { name: 'title', type: 'string', description: 'The component title' },
            { name: 'isVisible', type: 'boolean', description: 'Whether the component is visible' }
          ],
          methods: [
            { name: 'ngOnInit', description: 'Lifecycle hook', signature: 'ngOnInit(): void' },
            { name: 'onClick', description: 'Handle click events', signature: 'onClick(event: MouseEvent): void' }
          ]
        }
      ],
      navTabs: [
        { id: 'info', label: 'Info', href: '#info' },
        { id: 'source', label: 'Source', href: '#source' },
        { id: 'example', label: 'Example', href: '#example' }
      ]
    };
  }
}

import { Injectable } from '@angular/core';

declare const monaco: any;

@Injectable({
  providedIn: 'root'
})
export class TemplateEditorService {
  private editor: any;
  private onChangeCallback: ((value: string) => void) | null = null;

  initializeEditor(container: HTMLElement) {
    // Initialize Monaco Editor
    this.editor = monaco.editor.create(container, {
      value: '',
      language: 'html',
      theme: 'vs-dark',
      automaticLayout: true,
      minimap: {
        enabled: true
      },
      scrollBeyondLastLine: false,
      fontSize: 14,
      wordWrap: 'on',
      lineNumbers: 'on',
      roundedSelection: false,
      scrollbar: {
        horizontal: 'visible',
        vertical: 'visible'
      },
      overviewRulerLanes: 2,
      quickSuggestions: {
        other: true,
        comments: true,
        strings: true
      },
      parameterHints: {
        enabled: true
      },
      autoClosingBrackets: 'always',
      autoClosingQuotes: 'always',
      suggestOnTriggerCharacters: true,
      acceptSuggestionOnEnter: 'on',
      tabCompletion: 'on',
      wordBasedSuggestions: false
    });

    // Set up change listener
    this.editor.onDidChangeModelContent(() => {
      if (this.onChangeCallback) {
        this.onChangeCallback(this.editor.getValue());
      }
    });

    // Register custom language definitions
    this.registerHandlebarsLanguage();
  }

  setEditorContent(content: string, fileType: string) {
    if (this.editor) {
      const language = this.getLanguageFromFileType(fileType);
      const model = monaco.editor.createModel(content, language);
      this.editor.setModel(model);
    }
  }

  setOnChangeCallback(callback: (value: string) => void) {
    this.onChangeCallback = callback;
  }

  private getLanguageFromFileType(fileType: string): string {
    switch (fileType) {
      case 'hbs':
        return 'handlebars';
      case 'css':
      case 'scss':
        return 'css';
      case 'js':
        return 'javascript';
      case 'ts':
        return 'typescript';
      default:
        return 'html';
    }
  }

  private registerHandlebarsLanguage() {
    // Register Handlebars language for Monaco Editor
    if (monaco.languages.getLanguages().find((lang: any) => lang.id === 'handlebars')) {
      return; // Already registered
    }

    monaco.languages.register({ id: 'handlebars' });

    monaco.languages.setMonarchTokensProvider('handlebars', {
      tokenizer: {
        root: [
          [/\{\{\{/, { token: 'keyword', next: '@handlebars_unescaped' }],
          [/\{\{/, { token: 'keyword', next: '@handlebars' }],
          [/<!DOCTYPE/, 'metatag', '@doctype'],
          [/<!--/, 'comment', '@comment'],
          [/(<)(\w+)/, ['delimiter', { token: 'tag', next: '@tag' }]],
          [/(<\/)(\w+)/, ['delimiter', { token: 'tag', next: '@tag' }]],
          [/</, 'delimiter'],
          [/[^<]+/]
        ],

        handlebars_unescaped: [
          [/\}\}\}/, { token: 'keyword', next: '@pop' }],
          [/[^}]+/, 'variable']
        ],

        handlebars: [
          [/\}\}/, { token: 'keyword', next: '@pop' }],
          [/#if|#unless|#each|#with|\/if|\/unless|\/each|\/with/, 'keyword'],
          [/[a-zA-Z_][\w]*/, 'variable'],
          [/[^}]+/, 'variable']
        ],

        comment: [
          [/-->/, 'comment', '@pop'],
          [/[^-]+/, 'comment'],
          [/./, 'comment']
        ],

        doctype: [
          [/[^>]+/, 'metatag.content'],
          [/>/, 'metatag', '@pop']
        ],

        tag: [
          [/[ \t\r\n]+/, 'white'],
          [/(\w+)(\s*=\s*)("([^"]*)")/, ['attribute.name', 'delimiter', 'attribute.value', 'attribute.value']],
          [/(\w+)(\s*=\s*)('([^']*)')/, ['attribute.name', 'delimiter', 'attribute.value', 'attribute.value']],
          [/\w+/, 'attribute.name'],
          [/>/, 'delimiter', '@pop']
        ]
      }
    });

    monaco.languages.setLanguageConfiguration('handlebars', {
      comments: {
        blockComment: ['<!--', '-->']
      },
      brackets: [
        ['<', '>'],
        ['{{', '}}'],
        ['{{{', '}}}']
      ],
      autoClosingPairs: [
        { open: '<', close: '>' },
        { open: '{{', close: '}}' },
        { open: '{{{', close: '}}}' },
        { open: '"', close: '"' },
        { open: "'", close: "'" }
      ],
      surroundingPairs: [
        { open: '<', close: '>' },
        { open: '{{', close: '}}' },
        { open: '{{{', close: '}}}' },
        { open: '"', close: '"' },
        { open: "'", close: "'" }
      ]
    });
  }

  destroy() {
    if (this.editor) {
      this.editor.dispose();
      this.editor = null;
    }
  }
}

import { Injectable } from '@angular/core';
import * as CryptoJS from 'crypto-js';

/**
 * Datos requeridos para registrar un nuevo usuario.
 */
export interface UsuarioRegistro {
  /** Nombre completo del usuario */
  nombre: string;
  /** Correo electrónico del usuario */
  email: string;
  /** Contraseña en texto plano (se encriptará) */
  password: string;
}

/**
 * Representa un usuario persistido en el sistema.
 */
export interface Usuario {
  /** Identificador único del usuario */
  id: string;
  /** Nombre completo */
  nombre: string;
  /** Correo electrónico normalizado */
  email: string;
  /** Hash de la contraseña generado con PBKDF2 */
  passwordHash: string;
  /** Salt aleatorio usado para el hash */
  salt: string;
  /** Fecha de registro */
  fechaRegistro: Date;
  /** Estado de actividad del usuario */
  activo: boolean;
}

/**
 * Servicio para gestionar usuarios en localStorage.
 * Incluye registro, login, logout y validación de contraseñas.
 */
@Injectable({
  providedIn: 'root'
})
export class UsuarioService {

  /** Clave usada para almacenar la lista de usuarios en localStorage */
  private readonly usersKey = 'users';

  /** Clave usada para almacenar el usuario actual en localStorage */
  private readonly currentUserKey = 'currentUser';

  /** Número de iteraciones para PBKDF2 */
  private readonly PBKDF2_ITERATIONS = 100000;

  /** Longitud de la clave generada por PBKDF2 */
  private readonly KEY_LENGTH = 256;

  constructor() {}

  /**
   * Obtiene todos los usuarios almacenados en localStorage.
   * @returns Lista de usuarios o un array vacío si no hay datos válidos.
   */
  obtenerTodosLosUsuarios(): Usuario[] {
    const data = localStorage.getItem(this.usersKey);
    try {
      const usuarios = JSON.parse(data || '[]');
      return Array.isArray(usuarios) ? usuarios : [];
    } catch {
      return [];
    }
  }

  /**
   * Verifica si un email ya está registrado en el sistema.
   * @param email Correo electrónico a comprobar.
   * @returns `true` si existe, `false` en caso contrario.
   */
  verificarUsuarioExiste(email: string): boolean {
    const usuarios = this.obtenerTodosLosUsuarios();
    const emailNormalizado = email.trim().toLowerCase();
    return usuarios.some((u: Usuario) => u.email.trim().toLowerCase() === emailNormalizado);
  }

  /**
   * Genera un salt aleatorio para hashing.
   * @returns Cadena aleatoria en formato hexadecimal.
   */
  private generarSalt(): string {
    return CryptoJS.lib.WordArray.random(128 / 8).toString();
  }

  /**
   * Aplica PBKDF2 al password usando SHA256.
   * @param password Contraseña en texto plano.
   * @param salt Salt asociado al usuario.
   * @returns Hash resultante en formato string.
   */
  private aplicarPBKDF2(password: string, salt: string): string {
    return CryptoJS.PBKDF2(password, salt, {
      keySize: this.KEY_LENGTH / 32,
      iterations: this.PBKDF2_ITERATIONS,
      hasher: CryptoJS.algo.SHA256
    }).toString();
  }

  /**
   * Genera un identificador único para cada usuario.
   * @returns ID único con prefijo `user_`.
   */
  private generarIdUnico(): string {
    return 'user_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  }

  /**
   * Crea un nuevo usuario con contraseña encriptada.
   * @param usuarioRegistro Datos de registro (nombre, email, password).
   * @returns Usuario completo con hash y salt.
   * @throws Error si el email ya existe.
   */
  generarUsuario(usuarioRegistro: UsuarioRegistro): Usuario {
    if (this.verificarUsuarioExiste(usuarioRegistro.email)) {
      throw new Error('El usuario con este email ya existe');
    }

    const salt = this.generarSalt();
    const passwordHash = this.aplicarPBKDF2(usuarioRegistro.password, salt);

    return {
      id: this.generarIdUnico(),
      email: usuarioRegistro.email.toLowerCase().trim(),
      nombre: usuarioRegistro.nombre.trim(),
      passwordHash,
      salt,
      fechaRegistro: new Date(),
      activo: true
    };
  }

  /**
   * Verifica la fortaleza de una contraseña.
   * @param password Contraseña a evaluar.
   * @returns Objeto con `esSegura` y lista de errores.
   */
  verificarFortalezaPassword(password: string): { esSegura: boolean; errores: string[] } {
    const errores: string[] = [];

    if (password.length < 8) errores.push('Mínimo 8 caracteres');
    if (!/[A-Z]/.test(password)) errores.push('Al menos una mayúscula');
    if (!/[a-z]/.test(password)) errores.push('Al menos una minúscula');
    if (!/[0-9]/.test(password)) errores.push('Al menos un número');
    if (!/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) errores.push('Al menos un carácter especial');

    return { esSegura: errores.length === 0, errores };
  }

  /**
   * Registra un usuario en localStorage.
   * @param usuario Usuario a registrar.
   */
  registrar(usuario: Usuario): void {
    const users = this.obtenerTodosLosUsuarios();
    users.push(usuario);
    localStorage.setItem(this.usersKey, JSON.stringify(users));
  }

  /**
   * Devuelve todos los usuarios registrados.
   * @returns Lista de usuarios.
   */
  getUsuarios(): Usuario[] {
    return this.obtenerTodosLosUsuarios();
  }

  /**
   * Guarda el usuario actual en localStorage y lanza un evento de login.
   * @param usuario Usuario que inicia sesión.
   */
  setUsuarioActual(usuario: Usuario): void {
    localStorage.setItem(this.currentUserKey, JSON.stringify(usuario));

    window.dispatchEvent(new CustomEvent('usuarioIniciado', {
      detail: usuario
    }));
  }

  /**
   * Obtiene el usuario actualmente logueado.
   * @returns Usuario actual o `null` si no hay sesión.
   */
  getUsuarioActual(): Usuario | null {
    const data = localStorage.getItem(this.currentUserKey);
    return data ? JSON.parse(data) as Usuario : null;
  }

  /**
   * Cierra la sesión del usuario actual y lanza un evento de logout.
   */
  logout(): void {
    localStorage.removeItem(this.currentUserKey);
    window.dispatchEvent(new CustomEvent('usuarioCerrado'));
  }

  /**
   * Realiza login verificando email/nombre y contraseña.
   * @param emailOrUser Email o nombre del usuario.
   * @param password Contraseña en texto plano.
   * @returns Usuario si las credenciales son correctas, `null` en caso contrario.
   */
  login(emailOrUser: string, password: string): Usuario | null {
    const usuarios = this.obtenerTodosLosUsuarios();
    const usuario = usuarios.find(u =>
      u.email === emailOrUser.trim().toLowerCase() ||
      u.nombre === emailOrUser.trim()
    );

    if (!usuario) return null;

    const hash = this.aplicarPBKDF2(password, usuario.salt);
    return hash === usuario.passwordHash ? usuario : null;
  }
}

import { Injectable } from '@angular/core';

declare const JSZip: any;

@Injectable({
  providedIn: 'root'
})
export class ZipExportService {

  exportTemplates(files: any[]) {
    const zip = new JSZip();

    // Add all template files to the ZIP
    files.forEach(file => {
      zip.file(file.path, file.content);
    });

    // Add a README with instructions
    const readme = this.generateReadme();
    zip.file('README.md', readme);

    // Generate and download the ZIP file
    zip.generateAsync({ type: 'blob' })
      .then((content: Blob) => {
        this.downloadBlob(content, 'compodoc-templates.zip');
      });
  }

  private generateReadme(): string {
    return `# Compodoc Custom Templates

This ZIP file contains customized templates for Compodoc documentation generation.

## Contents

- **Templates** (\`.hbs\` files): Handlebars templates for generating documentation pages
- **Styles** (\`.css\` files): Stylesheets for customizing the appearance
- **Scripts** (\`.js\` files): JavaScript files for additional functionality

## Usage

1. Extract this ZIP file to a directory on your system
2. Use the \`--templates\` flag when running Compodoc to specify the path to your custom templates:

   \`\`\`bash
   compodoc -p tsconfig.json --templates ./path/to/custom/templates/
   \`\`\`

## Template Structure

- \`page.hbs\` - Main page template
- \`partials/\` - Directory containing partial templates
- \`styles/\` - Directory containing CSS files
- \`js/\` - Directory containing JavaScript files

## Customization Tips

1. **Templates**: Use Handlebars syntax to customize the HTML structure
2. **Styles**: Modify CSS to change colors, fonts, layout, etc.
3. **Scripts**: Add custom JavaScript functionality

## Backup

Always keep a backup of your original templates before making changes.

## Documentation

For more information about customizing Compodoc templates, visit:
https://compodoc.app/guides/template-customization.html

Generated by Compodoc Template Playground
`;
  }

  private downloadBlob(blob: Blob, filename: string) {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  }
}

