/* --- Estilos generales --- */
.zapatos {
  padding: 2.5rem;
  max-width: 1200px;
  margin: 0 auto;
  text-align: center;
  font-family: 'Poppins', sans-serif;
}

h2 {
  font-size: 2.4rem;
  font-weight: 700;
  color: #222;
  margin-bottom: 2.5rem;
  letter-spacing: 1px;
}

/* --- Rejilla de productos --- */
.galeria {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 2rem;
  justify-items: center;
}

/* --- Tarjeta individual --- */
.tarjeta {
  background: #fff;
  border-radius: 20px;
  overflow: hidden;
  width: 100%;
  max-width: 300px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.tarjeta:hover {
  transform: translateY(-6px);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.12);
}

.tarjeta img {
  width: 100%;
  height: 260px;
  object-fit: cover;
  border-bottom: 1px solid #eee;
}

.tarjeta h3 {
  margin-top: 1rem;
  font-size: 1.25rem;
  color: #333;
}

.precio {
  font-size: 1.1rem;
  font-weight: 600;
  color: #2b7cff;
  margin: 0.5rem 0 1.4rem;
}

/* --- Botón estilizado --- */
button {
  background: linear-gradient(135deg, #2b7cff, #0056d6);
  color: white;
  border: none;
  padding: 0.7rem 1.4rem;
  border-radius: 12px;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 600;
  transition: 0.25s ease;
  margin-bottom: 1.2rem;
}

button:hover {
  background: linear-gradient(135deg, #1f63d4, #0047b0);
  transform: scale(1.05);
}

/* --- Toaster (mensaje) centrado arriba --- */
.mensaje {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%) translateY(-20px);
  background: linear-gradient(135deg, #ff4b4b, #b30000);
  color: white;
  padding: 14px 26px;
  border-radius: 14px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.25);
  opacity: 0;
  font-size: 1rem;
  font-weight: 600;
  transition: opacity 0.45s ease, transform 0.45s ease;
  z-index: 1000;
  pointer-events: none;
}

.mensaje.visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* --- Responsive --- */
@media (max-width: 600px) {
  .tarjeta {
    max-width: 100%;
  }

  .tarjeta img {
    height: 200px;
  }

  h2 {
    font-size: 2rem;
  }
}
/* --- Rejilla de productos (centrado mejorado) --- */
.galeria {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.8rem;
  justify-items: center;     /* Centra cada tarjeta */
  justify-content: center;
  margin-left: 80px;  /* Centra TODA la fila en la página */
}

/* --- Tarjeta individual (ancho consistente) --- */
.tarjeta {
  width: 100%;
  max-width: 260px; /* ⬅️ Evita que se estiren y queden desalineadas */
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

